package Loops;

public class Program18_WhileLoop {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int num=1;
		while(num<=10) {
			System.out.print(num+" ");
			num++;
		
		}
		System.out.println();
		int num2=10;
		while(num2>=-2) {
			System.out.print(num2+" ");
			num2=num2-2;
		}
		

	}

}
